#include <stdio.h>
int run(int n) {
    static int total = 1;
    if (n == 0) return total;
    total += n;
    int child = run(n - 1);
    return child + total;
}
int main(void) {
    int a = run(2);
    int b = run(1);
    printf("%d %d", a, b);
    return 0;
}

