int main(void) {
    int a[2][3] = {{2, 4, 6}, {1, 3, 5}};
    for (int r = 0; r < 2; r++)
        for (int c = 1; c < 3; c++)
            a[r][c] += a[r][c - 1];
    int sum = 0;
    for (int i = 0; i < 6; i++) {
        int r = i / 3, c = i % 3;
        if ((r + c) % 2 == 0) sum += a[r][c];
        else sum -= a[r][c];
    }
    printf("%d %d %d\n", a[0][0], a[0][1], a[0][2]);
    printf("%d %d %d\n", a[1][0], a[1][1], a[1][2]);
    printf("sum=%d", sum);
    return 0;
}

#include <stdio.h>
typedef struct Node { int value; struct Node *next; } Node;
int main(void) {
    Node a = {4, NULL}, b = {7, NULL};
    Node c = {1, NULL}, d = {9, NULL};
    a.next = &b; b.next = &c; c.next = &d;
    Node *head = &a;
    Node *moved = head->next->next;
    head->next->next = moved->next;
    moved->next = head;
    head = moved;
    head->next->value += head->value;
    int total = 0;
    for (Node *p = head; p != NULL; p = p->next) {
        total = total * 2 + p->value;
        printf("%d%s", p->value, p->next ? " " : "\n");
    }
    printf("code=%d", total);
    return 0;
}

#include <stdio.h>
int emit(int n) {
    if (n <= 1) {
        printf("%d", n);
        return n;
    }
    int left = emit(n - 1);
    printf("A");
    int right = emit(n - 2);
    printf("B");
    return left + right;
}
int main(void) {
    int result = emit(3);
    printf("=%d", result);
    return 0;
}

#include <stdio.h>
int main(void) {
    int stack[4], top = 0;
    stack[top++] = 2;
    stack[top++] = 5;
    int first = stack[--top];
    stack[top++] = first - 1;
    int queue[4], front = 0, rear = 0;
    queue[rear++] = stack[--top];
    queue[rear++] = stack[--top];
    int x = queue[front++];
    queue[rear++] = x + 3;
    printf("%d|", x);
    while (front < rear) {
        int value = queue[front++];
        printf("%d", value);
        if (front < rear) printf(" ");
    }
    return 0;
}

class Parent {
    int x = 4;
    int read() { return x + 1; }
}
class Child extends Parent {
    int x = 9;
    @Override int read() { return x * 2; }
}
public class Main {
    public static void main(String[] args) {
        Parent p = new Child();
        Child c = (Child)p;
        System.out.print(p.x + ":" + p.read() + ":" + c.x);
    }
}

class Base {
    int x;
    Base(int x) {
        this.x = x;
        System.out.print("P" + x);
    }
    int value() { return x + 2; }
}
class Child extends Base {
    int x;
    Child(int v) {
        super(v + 1);
        this.x = v;
        System.out.print("C" + x);
    }
    int value(int add) { return super.value() + add; }
}
public class Main {
    public static void main(String[] args) {
        Child c = new Child(4);
        Base p = c;
        System.out.print("|" + p.value() + ":" + c.value(3));
    }
}

public class Main {
    static int calls = 0;
    static int calc(int n) {
        ++calls;
        if (n <= 1) return n;
        int a = calc(n - 2);
        int b = calc(n - 3);
        return a + b;
    }
    public static void main(String[] args) {
        int first = calc(5);
        int second = calc(4);
        System.out.print(first + ":" + second + ":" + calls);
    }
}

