public class Main {
    static int run(int[] a) {
        int result = 1;
        try {
            result = a[2] / a[0];
            return result + 2;
        } catch (ArithmeticException e) {
            result = 4;
            return result + 3;
        } finally {
            a[1] += result;
            result = 9;
        }
    }
    public static void main(String[] args) {
        int[] a = {0, 2, 8};
        int r = run(a);
        System.out.print(r + ":" + a[1]);
    }
}

