CREATE TABLE Credits(id INTEGER, points INTEGER);
CREATE TABLE Charges(id INTEGER, fee INTEGER);
INSERT INTO Credits VALUES (1,12),(2,24),(3,36),(4,48),(5,60);
INSERT INTO Charges VALUES (1,NULL),(1,6),(1,18),(2,30),(4,210),(9,100);
SELECT COUNT(*) AS result
FROM Credits AS current
WHERE current.points > (
    SELECT AVG(fee) FROM Charges
    WHERE Charges.id IN (
        SELECT prior.id FROM Credits AS prior
        WHERE prior.points < current.points
    )
);

CREATE TABLE Members(id INTEGER, grp TEXT);
CREATE TABLE Scores(mid INTEGER, points INTEGER);
